  "ui.wpAdminAgentFrameApp.feedback105": "현재 Gutenberg 문서를 완전히 불러오지 못했습니다({value1}). 변경하지 않았습니다.",
  "ui.wpAdminAgentFrameApp.feedback106": "현재 Gutenberg 문서는 바인딩된 청크 스냅샷으로만 사용할 수 있습니다. 필요한 모든 청크를 읽기 전에는 전체 문서 편집을 준비할 수 없습니다. 변경하지 않았습니다.",
  "ui.wpAdminAgentFrameApp.feedback107": "현재 Gutenberg 게시물에 저장되지 않은 변경 사항이 있습니다. Pixflow가 읽거나 콘텐츠 기반 편집을 준비하기 전에 저장 또는 업데이트하세요. 변경하지 않았습니다.",
  "ui.wpAdminAgentFrameApp.feedback108": "모든 Gutenberg 블록 지우기는 현재 지원되지 않습니다. Pixflow는 요청을 빈 내용으로의 교체로 해석하지 않았으며 변경하지 않았습니다.",
  "ui.wpAdminAgentFrameApp.feedback109": "Pixflow가 이 메시지가 대기 중인 질문의 답변인지 새 요청인지 판단하지 못했습니다. 검토를 준비하지 않았으며 변경하지 않았습니다.",
  "ui.wpAdminAgentFrameApp.feedback110": "현재 Gutenberg 문서는 청크로 나뉘어 아직 완전히 읽지 못했으므로 Pixflow가 전체 문서 검토를 준비할 수 없습니다. 변경하지 않았습니다.",
