  "ui.seoAudit.browserCoverageObservedObservedViewportSamples_c9c88985": "브라우저 커버리지: {observed}에서 관찰된 뷰포트 샘플, {unavailable}에서는 사용 불가능. URL 및 뷰포트별 최신 샘플. 제한된 익명 DOM 관찰, 포괄적인 JavaScript 커버리지, 시각적 픽셀 검사, 실제 사용자 측정 또는 확인된 수리 등이 포함되지 않습니다.",
